import { NextResponse } from "next/server";
import { generatedContentRepository } from "@/server/repositories/generated-content.repository";
import { saveContentImage } from "@/services/ai/image-storage";
import { uploadContentImageSchema } from "@/validations/content.validation";

/**
 * Receives an image generated by an external automation (see N8N_IMAGE_WEBHOOK_URL) and attaches
 * it to a content item exactly like the app's own automatic generation would — same storage
 * helper, same `imageUrl` column. Base64 in, because that's what the automation already has in
 * hand after calling an image-generation API; no multipart parsing needed.
 */
export async function POST(request: Request, context: RouteContext<"/api/automation/content/[id]/image">) {
  const { id } = await context.params;

  const content = await generatedContentRepository.findById(id);
  if (!content) {
    return NextResponse.json({ error: "Conteúdo não encontrado." }, { status: 404 });
  }

  const body = await request.json().catch(() => null);
  if (!body) {
    return NextResponse.json({ error: "Corpo da requisição precisa ser um JSON válido." }, { status: 400 });
  }

  const parsed = uploadContentImageSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.issues[0]?.message ?? "Dados inválidos." }, { status: 400 });
  }

  let buffer: Buffer;
  try {
    buffer = Buffer.from(parsed.data.imageBase64, "base64");
  } catch {
    return NextResponse.json({ error: "'imageBase64' não é um base64 válido." }, { status: 400 });
  }
  if (buffer.length === 0) {
    return NextResponse.json({ error: "'imageBase64' não é um base64 válido." }, { status: 400 });
  }

  const imageUrl = await saveContentImage(id, buffer, parsed.data.mimeType);
  await generatedContentRepository.updateImageUrl(id, imageUrl);

  return NextResponse.json({ contentId: id, imageUrl });
}
